#pragma once
#include "kernels/quantization_loops.hpp"
extern "C" {
uint32_t midi_quantization_test_cases,midi_quantization_test_failures;
uint32_t midi_quantization_test_first_failure,midi_quantization_test_mve;
}
namespace {
int quantization_selftest() {
#ifdef __ARM_FEATURE_MVE
    midi_quantization_test_mve=__ARM_FEATURE_MVE;
#endif
    // Exact binary ties, saturation endpoints and odd tails. Expected integers
    // are independent nearest-even results, not generated by the tested loop.
    constexpr float values[]={-40000.f,-32768.5f,-32767.5f,-32766.5f,-3.5f,-2.5f,-1.5f,-.5f,-0.f,0.f,.5f,1.5f,2.5f,3.5f,32765.5f,32766.5f,32767.5f,40000.f};
    constexpr int16_t expected[]={-32768,-32768,-32768,-32766,-4,-2,-2,0,0,0,0,2,2,4,32766,32766,32767,32767};
    alignas(16) float source[24],restored[24];alignas(16) int16_t quantized[24];
    auto fail=[&](){++midi_quantization_test_failures;if(!midi_quantization_test_first_failure)midi_quantization_test_first_failure=midi_quantization_test_cases;};
    for(unsigned shift=0;shift<4;++shift)for(unsigned count=1;count<=18;++count)for(unsigned scale=0;scale<2;++scale){
        ++midi_quantization_test_cases;
        for(unsigned i=0;i<24;++i){source[i]=0.f;quantized[i]=12345;restored[i]=12345.f;}
        for(unsigned i=0;i<count;++i)source[shift+i]=values[i]*(scale?.25f:1.f);
        if(!midi_ddsp::kernels::quantize_short(source+shift,quantized+shift,count,scale?4.f:1.f,-32768,32767)){fail();continue;}
        midi_ddsp::kernels::dequantize_short(quantized+shift,restored+shift,count,.25f);
        for(unsigned i=0;i<count;++i)if(quantized[shift+i]!=expected[i]||restored[shift+i]!=float(expected[i])*.25f)fail();
        for(unsigned i=0;i<shift;++i)if(quantized[i]!=12345||restored[i]!=12345.f)fail();
        for(unsigned i=shift+count;i<24;++i)if(quantized[i]!=12345||restored[i]!=12345.f)fail();
    }
    // A narrower symmetric/asymmetric quantization interval must saturate
    // before narrowing; repeat both vector and scalar tails.
    for(unsigned count=1;count<=18;++count){++midi_quantization_test_cases;
        if(!midi_ddsp::kernels::quantize_short(values,quantized,count,1.f,-2,3)){fail();continue;}
        for(unsigned i=0;i<count;++i){const int16_t e=expected[i]<-2?-2:expected[i]>3?3:expected[i];if(quantized[i]!=e)fail();}
    }
    // Exercise each vector lane immediately below, at, and above binary ties.
    for(int n=-255;n<=255;++n){++midi_quantization_test_cases;
        const float tie=float(n)+.5f;uint32_t bits;std::memcpy(&bits,&tie,4);
        const uint32_t below=bits+(tie<0.f?1U:uint32_t(-1));
        const uint32_t above=bits+(tie<0.f?uint32_t(-1):1U);
        source[0]=tie;std::memcpy(source+1,&below,4);std::memcpy(source+2,&above,4);source[3]=tie;
        const int16_t even=int16_t(n+(n&1));const int16_t e[]={even,int16_t(n),int16_t(n+1),even};
        if(!midi_ddsp::kernels::quantize_short(source,quantized,4,1.f,-32768,32767)){fail();continue;}
        for(unsigned i=0;i<4;++i)if(quantized[i]!=e[i])fail();
    }
    // Unsafe native-conversion inputs must request the original fallback.
    constexpr uint32_t unsafe[]={0x7fc00000U,0x7f800000U,0xff800000U,0x5f000000U};
    for(uint32_t bits:unsafe)for(unsigned count: {1U,4U,5U}){++midi_quantization_test_cases;
        for(float &v:source)std::memcpy(&v,&bits,4);
        if(midi_ddsp::kernels::quantize_short(source,quantized,count,1.f,-32768,32767))fail();
    }
    for(uint32_t bits:unsafe)for(unsigned lane=0;lane<8;++lane){++midi_quantization_test_cases;
        for(float &v:source)v=1.f;std::memcpy(source+lane,&bits,4);
        if(midi_ddsp::kernels::quantize_short(source,quantized,8,1.f,-32768,32767))fail();
    }
    return midi_quantization_test_failures?-620:0;
}
}
